#include <algorithm>
#include <array>
#include <iostream>
#include <numeric>
#include <stdexcept>
#include <vector>
using namespace std;using G=vector<unsigned>;using ll=long long;using I=__int128_t;using P=vector<I>;
void need(bool v,const char*s){if(!v)throw runtime_error(s);}I gcdI(I a,I b){if(a<0)a=-a;if(b<0)b=-b;while(b){I c=a%b;a=b;b=c;}return a;}string str(I a){if(!a)return "0";bool neg=a<0;if(neg)a=-a;string s;while(a){s.push_back('0'+a%10);a/=10;}if(neg)s.push_back('-');reverse(s.begin(),s.end());return s;}I fact(int n){I v=1;while(n)v*=n--;return v;}ll choose(int n,int r){if(r<0||r>n)return 0;ll a=1;for(int j=1;j<=r;j++)a=a*(n-j+1)/j;return a;}bool arc(const G&a,int u,int v){return a[u]>>v&1;}
P covers(const G&a){int n=a.size();vector<int>p(n);iota(p.begin(),p.end(),0);P f(n+1);do{int bad=0;for(int j=1;j<n;j++)bad+=!arc(a,p[j-1],p[j]);for(int r=bad+1;r<=n;r++)f[r]+=choose(n-1-bad,r-1-bad);}while(next_permutation(p.begin(),p.end()));for(int r=1;r<=n;r++){need(f[r]%fact(r)==0,"ordered/unordered factorial");f[r]/=fact(r);}return f;}
I Hwalk(const G&a){int n=a.size();I total=0;for(unsigned S=1;S<(1u<<n);S++){vector<I>v(n),w(n);for(int i=0;i<n;i++)v[i]=(S>>i)&1;for(int t=1;t<n;t++){fill(w.begin(),w.end(),0);for(int i=0;i<n;i++)if(v[i])for(unsigned q=a[i]&S;q;q&=q-1)w[__builtin_ctz(q)]+=v[i];v.swap(w);}I sum=accumulate(v.begin(),v.end(),I(0));if((n-__builtin_popcount(S))%2)total-=sum;else total+=sum;}return total;}
G trans(int n){G a(n);for(int i=0;i<n;i++)for(int j=i+1;j<n;j++)a[i]|=1u<<j;return a;}G cyclic(const G&a,const G&b,const G&c){G t(a.size()+b.size()+c.size());array<G,3>v{a,b,c};int offset[3]={0,(int)a.size(),(int)(a.size()+b.size())};for(int i=0;i<3;i++)for(int x=0;x<(int)v[i].size();x++){t[offset[i]+x]|=v[i][x]<<offset[i];int j=(i+1)%3;for(int y=0;y<(int)v[j].size();y++)t[offset[i]+x]|=1u<<(offset[j]+y);}return t;}
G matching(int r){int k=r-1;G q(2*k+1);for(int i=0;i<k;i++){q[i+1]|=1;q[0]|=1u<<(1+k+i);}for(int i=0;i<k;i++)for(int j=0;j<k;j++){if(i==j)q[1+k+i]|=1u<<(1+j);else q[1+j]|=1u<<(1+k+i);}for(int i=0;i<k;i++)for(int j=i+1;j<k;j++){q[1+i]|=1u<<(1+j);q[1+k+i]|=1u<<(1+k+j);}return q;}
G subst(const G&q,const G&v){G a(v.size()+q.size()-1);for(int i=0;i<(int)v.size();i++){a[i]=v[i];for(int j=1;j<(int)q.size();j++)if(arc(q,0,j))a[i]|=1u<<(v.size()+j-1);else a[v.size()+j-1]|=1u<<i;}for(int i=1;i<(int)q.size();i++)for(int j=1;j<(int)q.size();j++)if(arc(q,i,j))a[v.size()+i-1]|=1u<<(v.size()+j-1);return a;}
vector<P> kernel(const P&c){int n=c.size()-1;vector<P>K(n+1,P(n+1));for(int r=1;r<=n+1;r++)for(int s=1;s<=n+1;s++)for(int t=1;t<=n;t++){int count=0;for(int start=0;start<3;start++){int freq[3]={0,0,0};for(int z=0;z<r+s+t;z++)freq[(start+z)%3]++;count+=freq[0]==r&&freq[1]==s&&freq[2]==t;}K[r-1][s-1]+=fact(r)*fact(s)*fact(t)*c[t]*count;}return K;}
P mul(const P&a,const P&b){P c(a.size()+b.size()-1);for(int i=0;i<(int)a.size();i++)for(int j=0;j<(int)b.size();j++)c[i+j]+=a[i]*b[j];return c;}P polynomial(const P&c){P out(c.size()),fall{1};for(int r=0;r<(int)c.size();r++){for(int j=0;j<(int)fall.size();j++)out[j]+=c[r]*fall[j];fall=mul(fall,P{-r,1});}return out;}P central(P p,int parity){int d=(p.size()-1+1)/2;P u(d);for(int k=d-1;k>=0;k--){P b(parity?2:3);b.back()=1;for(int j=1;j<=k;j++)b=mul(b,P{-j*j,0,1});u[k]=p[b.size()-1];for(int j=0;j<(int)b.size();j++)p[j]-=u[k]*b[j];}for(I x:p)need(!x,"central basis exact recovery");return u;}
void printP(const P&p){cout<<"[";for(int i=0;i<(int)p.size();i++){if(i)cout<<",";cout<<str(p[i]);}cout<<"]";}void printG(const G&a){cout<<"[";for(int i=0;i<(int)a.size();i++){if(i)cout<<",";cout<<a[i];}cout<<"]";}
int main(){int small=0,actual=0;for(int n=1;n<=5;n++)for(int code=0;code<(1<<(n*(n-1)/2));code++){G v(n);int bit=0;for(int i=0;i<n;i++)for(int j=i+1;j<n;j++,bit++){bool f=code>>bit&1;v[f?i:j]|=1u<<(f?j:i);}P c=covers(v),u=central(polynomial(c),n%2);auto K=kernel(c);I g=0,Gc=0,C=0,centralC=0;for(int r=1;r<=n;r++){g=gcdI(g,fact(r)*c[r]);Gc=gcdI(Gc,fact(r-1)*fact(r)*c[r]);}for(auto&row:K)for(I x:row)C=gcdI(C,x);for(int k=0;k<(int)u.size();k++)centralC=gcdI(centralC,fact(k)*fact(k)*fact(2*k+1)*(n%2?1:k+1)*u[k]);need(C==centralC&&Gc*Gc%(g*C)==0&&g*g%C==0&&Gc*Gc*Gc*Gc%(C*C*C)==0,"all physical contents");if(n<=4){int L=max(2,(n+1)/2-1);I bankgcd=0;for(int i=1;i<=L;i++)for(int j=1;j<=L;j++){I h=Hwalk(cyclic(trans(i),trans(j),v));bankgcd=gcdI(bankgcd,h);actual++;}need(bankgcd==C,"actual short transitive bank");}small++;}
G v{382,420,88,706,810,972,18,597,204,327};P c=covers(v);need(c==P{0,7857,70551,185274,211989,124725,40851,7672,814,45,1},"literal ten-vertex cover vector");P p=polynomial(c),u=central(p,0);auto K=kernel(c);I g=0,Gc=0,C=0;for(int r=1;r<=10;r++){g=gcdI(g,fact(r)*c[r]);Gc=gcdI(Gc,fact(r-1)*fact(r)*c[r]);}for(auto&row:K)for(I x:row)C=gcdI(C,x);need(g==9&&Gc==27&&C==81,"strict three-level witness");vector<G>graphs{cyclic(trans(1),trans(1),v),cyclic(trans(1),trans(2),v),subst(matching(4),v)};P h;for(auto&a:graphs)h.push_back(Hwalk(a));need(h==P{164673,462591,94405041},"large independent walk inclusion-exclusion counts");need(gcdI(h[0],h[1])==81&&gcdI(c[1],h[2])==27&&h[2]%81==27,"sharp restriction contrast");P runs(4);vector<P>S(5,P(5));S[0][0]=1;for(int n=1;n<=4;n++)for(int r=1;r<=n;r++)S[n][r]=S[n-1][r-1]+r*S[n-1][r];for(int m=1;m<=4;m++){I value=Hwalk(subst(matching(4),trans(m)));for(int r=1;r<m;r++)value-=runs[r-1]*fact(r)*S[m][r];need(value%fact(m)==0,"integer interpolation");runs[m-1]=value/fact(m);}need(runs==P{91,101,44,6},"independent matching run coefficients");
cout<<"{\"status\":\"PASS\",\"literal_small_cover_profiles\":"<<small<<",\"literal_small_context_counts\":"<<actual<<",\"witness_covers\":";printP(c);cout<<",\"bin_profile\":";printP(p);cout<<",\"central_coordinates\":";printP(u);cout<<",\"contents\":[9,27,81],\"matching_runs\":";printP(runs);cout<<",\"walk_counts\":";printP(h);cout<<",\"graphs\":[";for(int i=0;i<3;i++){if(i)cout<<",";printG(graphs[i]);}cout<<"]}\n";
}
